insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-dinosaurs-trivia',
  'Dinosaurs Trivia: 8 Questions on the Giants of the Mesozoic',
  'From Tyrannosaurus rex to the long-necked sauropods: eight questions on the species, eras and extinction of the dinosaurs.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"What does the name Tyrannosaurus rex mean?","options":[{"id":"a","text":"Swift hunter","is_correct":false},{"id":"b","text":"Tyrant lizard king","is_correct":true},{"id":"c","text":"Three-horned face","is_correct":false},{"id":"d","text":"Terrible claw","is_correct":false}],"explanation":"It combines the Greek tyrannos (tyrant) and sauros (lizard) with the Latin rex (king)."},{"id":"q2","question":"Which of these periods is NOT part of the Mesozoic Era, the age of dinosaurs?","options":[{"id":"a","text":"Triassic","is_correct":false},{"id":"b","text":"Jurassic","is_correct":false},{"id":"c","text":"Cretaceous","is_correct":false},{"id":"d","text":"Devonian","is_correct":true}],"explanation":"The Devonian belongs to the earlier Paleozoic Era and ended about 359 million years ago, before dinosaurs appeared."},{"id":"q3","question":"What is Triceratops famous for?","options":[{"id":"a","text":"Three horns and a large neck frill","is_correct":true},{"id":"b","text":"Feathered wings","is_correct":false},{"id":"c","text":"A spiked tail club","is_correct":false},{"id":"d","text":"An extremely long neck","is_correct":false}],"explanation":"Its name means ''three-horned face''; it also carried a bony frill behind the skull."},{"id":"q4","question":"In which period did Tyrannosaurus rex live?","options":[{"id":"a","text":"Early Triassic","is_correct":false},{"id":"b","text":"Middle Jurassic","is_correct":false},{"id":"c","text":"Late Cretaceous","is_correct":true},{"id":"d","text":"Permian","is_correct":false}],"explanation":"T. rex lived about 68 to 66 million years ago, near the very end of the age of dinosaurs."},{"id":"q5","question":"Which dinosaur carried a double row of bony plates along its back?","options":[{"id":"a","text":"Velociraptor","is_correct":false},{"id":"b","text":"Brachiosaurus","is_correct":false},{"id":"c","text":"Stegosaurus","is_correct":true},{"id":"d","text":"Spinosaurus","is_correct":false}],"explanation":"Stegosaurus had upright plates on its back and four spikes on its tail."},{"id":"q6","question":"About how long ago did the non-avian dinosaurs go extinct?","options":[{"id":"a","text":"10,000 years ago","is_correct":false},{"id":"b","text":"5 million years ago","is_correct":false},{"id":"c","text":"66 million years ago","is_correct":true},{"id":"d","text":"200 million years ago","is_correct":false}],"explanation":"The extinction event at the end of the Cretaceous happened about 66 million years ago, linked to an asteroid impact."},{"id":"q7","question":"Which group of living animals descends directly from dinosaurs?","options":[{"id":"a","text":"Lizards","is_correct":false},{"id":"b","text":"Birds","is_correct":true},{"id":"c","text":"Turtles","is_correct":false},{"id":"d","text":"Snakes","is_correct":false}],"explanation":"Birds evolved from small feathered theropod dinosaurs, which is why they are considered living dinosaurs."},{"id":"q8","question":"Long-necked giants such as Brachiosaurus and Diplodocus belonged to which group?","options":[{"id":"a","text":"Theropods","is_correct":false},{"id":"b","text":"Ceratopsians","is_correct":false},{"id":"c","text":"Hadrosaurs","is_correct":false},{"id":"d","text":"Sauropods","is_correct":true}],"explanation":"Sauropods were the long-necked, plant-eating dinosaurs that included the largest land animals ever known."}]'::jsonb,
  null,
  array['dinosaurs', 'trivia', 'prehistory', 'extinction']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-dinosaurios',
  'Trivia de dinosaurios: 8 preguntas sobre los gigantes del Mesozoico',
  'Del Tyrannosaurus rex a los saurópodos de cuello largo: ocho preguntas sobre especies, eras y la extinción de los dinosaurios.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Qué significa el nombre Tyrannosaurus rex?","options":[{"id":"a","text":"Cazador veloz","is_correct":false},{"id":"b","text":"Rey de los lagartos tiranos","is_correct":true},{"id":"c","text":"Cara de tres cuernos","is_correct":false},{"id":"d","text":"Garra terrible","is_correct":false}],"explanation":"Combina el griego tyrannos (tirano) y sauros (lagarto) con el latín rex (rey)."},{"id":"q2","question":"¿Cuál de estos periodos NO forma parte de la era Mesozoica, la edad de los dinosaurios?","options":[{"id":"a","text":"Triásico","is_correct":false},{"id":"b","text":"Jurásico","is_correct":false},{"id":"c","text":"Cretácico","is_correct":false},{"id":"d","text":"Devónico","is_correct":true}],"explanation":"El Devónico pertenece a la era Paleozoica anterior y terminó hace unos 359 millones de años, antes de que aparecieran los dinosaurios."},{"id":"q3","question":"¿Por qué es famoso el Triceratops?","options":[{"id":"a","text":"Por sus tres cuernos y su gran placa craneal","is_correct":true},{"id":"b","text":"Por sus alas con plumas","is_correct":false},{"id":"c","text":"Por su maza de púas en la cola","is_correct":false},{"id":"d","text":"Por su cuello extremadamente largo","is_correct":false}],"explanation":"Su nombre significa «cara de tres cuernos»; además llevaba una gola ósea detrás del cráneo."},{"id":"q4","question":"¿En qué periodo vivió el Tyrannosaurus rex?","options":[{"id":"a","text":"Triásico inferior","is_correct":false},{"id":"b","text":"Jurásico medio","is_correct":false},{"id":"c","text":"Cretácico superior","is_correct":true},{"id":"d","text":"Pérmico","is_correct":false}],"explanation":"El T. rex vivió hace unos 68 a 66 millones de años, casi al final de la edad de los dinosaurios."},{"id":"q5","question":"¿Qué dinosaurio llevaba una doble hilera de placas óseas en el lomo?","options":[{"id":"a","text":"Velociraptor","is_correct":false},{"id":"b","text":"Brachiosaurus","is_correct":false},{"id":"c","text":"Stegosaurus","is_correct":true},{"id":"d","text":"Spinosaurus","is_correct":false}],"explanation":"El estegosaurio tenía placas verticales en el lomo y cuatro púas en la cola."},{"id":"q6","question":"¿Hace cuánto tiempo se extinguieron los dinosaurios no aviares?","options":[{"id":"a","text":"Hace 10 000 años","is_correct":false},{"id":"b","text":"Hace 5 millones de años","is_correct":false},{"id":"c","text":"Hace 66 millones de años","is_correct":true},{"id":"d","text":"Hace 200 millones de años","is_correct":false}],"explanation":"La extinción de finales del Cretácico ocurrió hace unos 66 millones de años, asociada al impacto de un asteroide."},{"id":"q7","question":"¿Qué grupo de animales actuales desciende directamente de los dinosaurios?","options":[{"id":"a","text":"Los lagartos","is_correct":false},{"id":"b","text":"Las aves","is_correct":true},{"id":"c","text":"Las tortugas","is_correct":false},{"id":"d","text":"Las serpientes","is_correct":false}],"explanation":"Las aves evolucionaron de pequeños dinosaurios terópodos con plumas, por lo que se consideran dinosaurios vivientes."},{"id":"q8","question":"¿A qué grupo pertenecían gigantes de cuello largo como Brachiosaurus y Diplodocus?","options":[{"id":"a","text":"Terópodos","is_correct":false},{"id":"b","text":"Ceratopsios","is_correct":false},{"id":"c","text":"Hadrosaurios","is_correct":false},{"id":"d","text":"Saurópodos","is_correct":true}],"explanation":"Los saurópodos eran dinosaurios herbívoros de cuello largo que incluyen a los mayores animales terrestres conocidos."}]'::jsonb,
  null,
  array['dinosaurios', 'trivia', 'prehistoria', 'extinción']::text[],
  3,
  'published',
  false,
  false,
  now()
)
