insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-pre-columbian-civilizations-trivia',
  'Pre-Columbian Civilizations Trivia: Maya, Aztec and Inca',
  'Eight questions on the great civilizations of the Americas before 1492: their cities, languages, monuments and empires.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Which civilization built the citadel of Machu Picchu?","options":[{"id":"a","text":"The Maya","is_correct":false},{"id":"b","text":"The Aztec","is_correct":false},{"id":"c","text":"The Inca","is_correct":true},{"id":"d","text":"The Olmec","is_correct":false}],"explanation":"Machu Picchu was built in the 15th century, probably as an estate for the Inca emperor Pachacuti."},{"id":"q2","question":"What was the capital of the Aztec Empire?","options":[{"id":"a","text":"Cusco","is_correct":false},{"id":"b","text":"Tenochtitlan","is_correct":true},{"id":"c","text":"Chichén Itzá","is_correct":false},{"id":"d","text":"Teotihuacan","is_correct":false}],"explanation":"Tenochtitlan stood on an island in Lake Texcoco, where Mexico City is today."},{"id":"q3","question":"The Maya civilization developed mainly in which region?","options":[{"id":"a","text":"The Andes mountains","is_correct":false},{"id":"b","text":"The Amazon basin","is_correct":false},{"id":"c","text":"The Yucatán Peninsula and Central America","is_correct":true},{"id":"d","text":"The Caribbean islands","is_correct":false}],"explanation":"Maya cities spread across present-day south-east Mexico, Guatemala, Belize and parts of Honduras and El Salvador."},{"id":"q4","question":"Which civilization is famous for its colossal carved stone heads?","options":[{"id":"a","text":"The Olmec","is_correct":true},{"id":"b","text":"The Inca","is_correct":false},{"id":"c","text":"The Aztec","is_correct":false},{"id":"d","text":"The Toltec","is_correct":false}],"explanation":"Seventeen Olmec colossal heads, carved from basalt, have been found along Mexico''s Gulf Coast."},{"id":"q5","question":"Quechua was the main language of which civilization?","options":[{"id":"a","text":"The Maya","is_correct":false},{"id":"b","text":"The Aztec","is_correct":false},{"id":"c","text":"The Inca","is_correct":true},{"id":"d","text":"The Zapotec","is_correct":false}],"explanation":"The Inca spread Quechua across their empire; it is still spoken by millions in the Andes."},{"id":"q6","question":"The pyramid known as El Castillo or Temple of Kukulcán stands at which site?","options":[{"id":"a","text":"Tikal","is_correct":false},{"id":"b","text":"Chichén Itzá","is_correct":true},{"id":"c","text":"Palenque","is_correct":false},{"id":"d","text":"Tenochtitlan","is_correct":false}],"explanation":"El Castillo is the central pyramid of Chichén Itzá, a great Maya city in Yucatán."},{"id":"q7","question":"The Inca Empire stretched mainly along which mountain range?","options":[{"id":"a","text":"The Rocky Mountains","is_correct":false},{"id":"b","text":"The Sierra Madre","is_correct":false},{"id":"c","text":"The Andes","is_correct":true},{"id":"d","text":"The Appalachians","is_correct":false}],"explanation":"At its height the empire ran along the Andes from present-day Colombia to central Chile."},{"id":"q8","question":"Which pre-Columbian civilization developed the most complete writing system in the Americas?","options":[{"id":"a","text":"The Inca","is_correct":false},{"id":"b","text":"The Aztec","is_correct":false},{"id":"c","text":"The Maya","is_correct":true},{"id":"d","text":"The Taíno","is_correct":false}],"explanation":"Maya glyphs could record sounds and ideas fully; the Inca kept records with knotted cords called quipu instead."}]'::jsonb,
  null,
  array['history', 'pre-columbian', 'maya', 'aztec', 'inca']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-civilizaciones-precolombinas',
  'Trivia de civilizaciones precolombinas: mayas, aztecas e incas',
  'Ocho preguntas sobre las grandes civilizaciones de América antes de 1492: sus ciudades, lenguas, monumentos e imperios.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Qué civilización construyó la ciudadela de Machu Picchu?","options":[{"id":"a","text":"La maya","is_correct":false},{"id":"b","text":"La azteca","is_correct":false},{"id":"c","text":"La inca","is_correct":true},{"id":"d","text":"La olmeca","is_correct":false}],"explanation":"Machu Picchu se construyó en el siglo XV, probablemente como residencia del emperador inca Pachacútec."},{"id":"q2","question":"¿Cuál era la capital del Imperio azteca?","options":[{"id":"a","text":"Cuzco","is_correct":false},{"id":"b","text":"Tenochtitlan","is_correct":true},{"id":"c","text":"Chichén Itzá","is_correct":false},{"id":"d","text":"Teotihuacán","is_correct":false}],"explanation":"Tenochtitlan se alzaba sobre una isla del lago de Texcoco, donde hoy está Ciudad de México."},{"id":"q3","question":"¿En qué región se desarrolló principalmente la civilización maya?","options":[{"id":"a","text":"En la cordillera de los Andes","is_correct":false},{"id":"b","text":"En la cuenca del Amazonas","is_correct":false},{"id":"c","text":"En la península de Yucatán y Centroamérica","is_correct":true},{"id":"d","text":"En las islas del Caribe","is_correct":false}],"explanation":"Las ciudades mayas se extendieron por el sureste de México, Guatemala, Belice y partes de Honduras y El Salvador."},{"id":"q4","question":"¿Qué civilización es famosa por sus cabezas colosales talladas en piedra?","options":[{"id":"a","text":"La olmeca","is_correct":true},{"id":"b","text":"La inca","is_correct":false},{"id":"c","text":"La azteca","is_correct":false},{"id":"d","text":"La tolteca","is_correct":false}],"explanation":"Se han encontrado diecisiete cabezas colosales olmecas, talladas en basalto, en la costa del golfo de México."},{"id":"q5","question":"¿De qué civilización era el quechua la lengua principal?","options":[{"id":"a","text":"La maya","is_correct":false},{"id":"b","text":"La azteca","is_correct":false},{"id":"c","text":"La inca","is_correct":true},{"id":"d","text":"La zapoteca","is_correct":false}],"explanation":"Los incas extendieron el quechua por todo su imperio; hoy lo hablan millones de personas en los Andes."},{"id":"q6","question":"¿En qué sitio arqueológico está la pirámide conocida como El Castillo o templo de Kukulcán?","options":[{"id":"a","text":"Tikal","is_correct":false},{"id":"b","text":"Chichén Itzá","is_correct":true},{"id":"c","text":"Palenque","is_correct":false},{"id":"d","text":"Tenochtitlan","is_correct":false}],"explanation":"El Castillo es la pirámide central de Chichén Itzá, la gran ciudad maya de Yucatán."},{"id":"q7","question":"¿A lo largo de qué cordillera se extendía principalmente el Imperio inca?","options":[{"id":"a","text":"Las montañas Rocosas","is_correct":false},{"id":"b","text":"La Sierra Madre","is_correct":false},{"id":"c","text":"Los Andes","is_correct":true},{"id":"d","text":"Los Apalaches","is_correct":false}],"explanation":"En su apogeo, el imperio recorría los Andes desde la actual Colombia hasta el centro de Chile."},{"id":"q8","question":"¿Qué civilización precolombina desarrolló el sistema de escritura más completo de América?","options":[{"id":"a","text":"La inca","is_correct":false},{"id":"b","text":"La azteca","is_correct":false},{"id":"c","text":"La maya","is_correct":true},{"id":"d","text":"La taína","is_correct":false}],"explanation":"Los glifos mayas podían registrar sonidos e ideas por completo; los incas usaban cuerdas anudadas llamadas quipus."}]'::jsonb,
  null,
  array['historia', 'precolombino', 'mayas', 'aztecas', 'incas']::text[],
  3,
  'published',
  false,
  false,
  now()
)
