insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-norse-mythology-trivia',
  'Norse Mythology Trivia: Gods, Worlds and Sagas',
  'Eight questions on the mythology of the Vikings: Odin, Thor, the nine worlds, Valhalla and the coming of Ragnarök.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"Who is the chief god of the Norse pantheon?","options":[{"id":"a","text":"Thor","is_correct":false},{"id":"b","text":"Loki","is_correct":false},{"id":"c","text":"Odin","is_correct":true},{"id":"d","text":"Balder","is_correct":false}],"explanation":"Odin, the Allfather, rules Asgard and is associated with wisdom, war and poetry."},{"id":"q2","question":"What is the name of Thor''s hammer?","options":[{"id":"a","text":"Gungnir","is_correct":false},{"id":"b","text":"Mjölnir","is_correct":true},{"id":"c","text":"Gram","is_correct":false},{"id":"d","text":"Skofnung","is_correct":false}],"explanation":"Mjölnir was forged by dwarves; Gungnir is Odin''s spear."},{"id":"q3","question":"In Norse mythology, what is Asgard?","options":[{"id":"a","text":"The land of the dead","is_correct":false},{"id":"b","text":"The home of the Æsir gods","is_correct":true},{"id":"c","text":"The world of the giants","is_correct":false},{"id":"d","text":"The realm of the dwarves","is_correct":false}],"explanation":"Asgard is the realm of the Æsir, the main family of Norse gods; the giants live in Jötunheim."},{"id":"q4","question":"What is Yggdrasil?","options":[{"id":"a","text":"A magical ship","is_correct":false},{"id":"b","text":"The world tree","is_correct":true},{"id":"c","text":"Odin''s spear","is_correct":false},{"id":"d","text":"A sea serpent","is_correct":false}],"explanation":"Yggdrasil is the immense ash tree that connects the nine worlds of Norse cosmology."},{"id":"q5","question":"Which foretold event brings about the destruction of the gods?","options":[{"id":"a","text":"Ragnarök","is_correct":true},{"id":"b","text":"Fimbulvetr","is_correct":false},{"id":"c","text":"Völuspá","is_correct":false},{"id":"d","text":"Gjallarhorn","is_correct":false}],"explanation":"Ragnarök is the prophesied final battle in which Odin, Thor and many others fall; Fimbulvetr is the great winter that precedes it."},{"id":"q6","question":"Who is the trickster god of Norse mythology?","options":[{"id":"a","text":"Heimdall","is_correct":false},{"id":"b","text":"Tyr","is_correct":false},{"id":"c","text":"Loki","is_correct":true},{"id":"d","text":"Njord","is_correct":false}],"explanation":"Loki, son of giants and blood-brother of Odin, is the shape-shifting schemer of the sagas."},{"id":"q7","question":"According to Norse cosmology, how many worlds does Yggdrasil connect?","options":[{"id":"a","text":"Seven","is_correct":false},{"id":"b","text":"Nine","is_correct":true},{"id":"c","text":"Three","is_correct":false},{"id":"d","text":"Twelve","is_correct":false}],"explanation":"The poems speak of nine worlds, among them Asgard, Midgard and Jötunheim."},{"id":"q8","question":"What is Valhalla?","options":[{"id":"a","text":"The rainbow bridge between worlds","is_correct":false},{"id":"b","text":"Odin''s hall where slain warriors are received","is_correct":true},{"id":"c","text":"The fortress of the giants","is_correct":false},{"id":"d","text":"The forest of the elves","is_correct":false}],"explanation":"Valkyries carry warriors fallen in battle to Valhalla, where they prepare for Ragnarök."}]'::jsonb,
  null,
  array['norse mythology', 'vikings', 'mythology', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
