values (
  'es-trivia-mitologia-nordica',
  'Trivia de mitología nórdica: dioses, mundos y sagas',
  'Ocho preguntas sobre la mitología de los vikingos: Odín, Thor, los nueve mundos, el Valhalla y la llegada del Ragnarök.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'culture'),
  '[{"id":"q1","question":"¿Quién es el dios principal del panteón nórdico?","options":[{"id":"a","text":"Thor","is_correct":false},{"id":"b","text":"Loki","is_correct":false},{"id":"c","text":"Odín","is_correct":true},{"id":"d","text":"Balder","is_correct":false}],"explanation":"Odín, el Padre de Todos, gobierna Asgard y se asocia con la sabiduría, la guerra y la poesía."},{"id":"q2","question":"¿Cómo se llama el martillo de Thor?","options":[{"id":"a","text":"Gungnir","is_correct":false},{"id":"b","text":"Mjölnir","is_correct":true},{"id":"c","text":"Gram","is_correct":false},{"id":"d","text":"Skofnung","is_correct":false}],"explanation":"Mjölnir fue forjado por enanos; Gungnir es la lanza de Odín."},{"id":"q3","question":"En la mitología nórdica, ¿qué es Asgard?","options":[{"id":"a","text":"La tierra de los muertos","is_correct":false},{"id":"b","text":"El hogar de los dioses Æsir","is_correct":true},{"id":"c","text":"El mundo de los gigantes","is_correct":false},{"id":"d","text":"El reino de los enanos","is_correct":false}],"explanation":"Asgard es el reino de los Æsir, la familia principal de dioses nórdicos; los gigantes viven en Jötunheim."},{"id":"q4","question":"¿Qué es Yggdrasil?","options":[{"id":"a","text":"Un barco mágico","is_correct":false},{"id":"b","text":"El árbol del mundo","is_correct":true},{"id":"c","text":"La lanza de Odín","is_correct":false},{"id":"d","text":"Una serpiente marina","is_correct":false}],"explanation":"Yggdrasil es el inmenso fresno que conecta los nueve mundos de la cosmología nórdica."},{"id":"q5","question":"¿Qué evento profetizado anuncia la destrucción de los dioses?","options":[{"id":"a","text":"El Ragnarök","is_correct":true},{"id":"b","text":"El Fimbulvetr","is_correct":false},{"id":"c","text":"La Völuspá","is_correct":false},{"id":"d","text":"El Gjallarhorn","is_correct":false}],"explanation":"El Ragnarök es la batalla final profetizada en la que caen Odín, Thor y otros; el Fimbulvetr es el gran invierno que la precede."},{"id":"q6","question":"¿Quién es el dios embaucador de la mitología nórdica?","options":[{"id":"a","text":"Heimdall","is_correct":false},{"id":"b","text":"Tyr","is_correct":false},{"id":"c","text":"Loki","is_correct":true},{"id":"d","text":"Njord","is_correct":false}],"explanation":"Loki, hijo de gigantes y hermano de sangre de Odín, es el tramposo cambiaformas de las sagas."},{"id":"q7","question":"Según la cosmología nórdica, ¿cuántos mundos conecta Yggdrasil?","options":[{"id":"a","text":"Siete","is_correct":false},{"id":"b","text":"Nueve","is_correct":true},{"id":"c","text":"Tres","is_correct":false},{"id":"d","text":"Doce","is_correct":false}],"explanation":"Los poemas hablan de nueve mundos, entre ellos Asgard, Midgard y Jötunheim."},{"id":"q8","question":"¿Qué es el Valhalla?","options":[{"id":"a","text":"El puente de arcoíris entre los mundos","is_correct":false},{"id":"b","text":"El salón de Odín donde llegan los guerreros caídos","is_correct":true},{"id":"c","text":"La fortaleza de los gigantes","is_correct":false},{"id":"d","text":"El bosque de los elfos","is_correct":false}],"explanation":"Las valquirias llevan a los guerreros caídos en combate al Valhalla, donde se preparan para el Ragnarök."}]'::jsonb,
  null,
  array['mitología nórdica', 'vikingos', 'mitología', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
