   is_featured, is_ai_generated, published_at)
values (
  'en-great-explorers-trivia',
  'Great Explorers Trivia: The Voyages That Mapped the World',
  'Eight questions on the classic age of exploration: Columbus, Magellan, Marco Polo and the routes that joined the continents.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Which explorer crossed the Atlantic in 1492 and reached the Caribbean under the Spanish crown?","options":[{"id":"a","text":"Amerigo Vespucci","is_correct":false},{"id":"b","text":"Christopher Columbus","is_correct":true},{"id":"c","text":"Ferdinand Magellan","is_correct":false},{"id":"d","text":"Vasco da Gama","is_correct":false}],"explanation":"Columbus made landfall in the Caribbean in October 1492 on the first of his four voyages."},{"id":"q2","question":"Whose expedition completed the first circumnavigation of the Earth?","options":[{"id":"a","text":"Ferdinand Magellan''s","is_correct":true},{"id":"b","text":"James Cook''s","is_correct":false},{"id":"c","text":"Francis Drake''s","is_correct":false},{"id":"d","text":"Vasco da Gama''s","is_correct":false}],"explanation":"Magellan died in the Philippines in 1521; Juan Sebastián Elcano finished the voyage in 1522."},{"id":"q3","question":"Which Portuguese navigator first reached India by sea, sailing around Africa?","options":[{"id":"a","text":"Vasco da Gama","is_correct":true},{"id":"b","text":"Bartolomeu Dias","is_correct":false},{"id":"c","text":"Pedro Álvares Cabral","is_correct":false},{"id":"d","text":"Ferdinand Magellan","is_correct":false}],"explanation":"Da Gama reached Calicut in 1498, opening the sea route from Europe to India."},{"id":"q4","question":"Who was the first European to see the eastern shore of the Pacific Ocean, in 1513?","options":[{"id":"a","text":"Hernán Cortés","is_correct":false},{"id":"b","text":"Vasco Núñez de Balboa","is_correct":true},{"id":"c","text":"Francisco Pizarro","is_correct":false},{"id":"d","text":"Ferdinand Magellan","is_correct":false}],"explanation":"Balboa crossed the Isthmus of Panama and reached the Pacific, which he called the South Sea."},{"id":"q5","question":"Which Venetian merchant travelled to China and described the court of Kublai Khan?","options":[{"id":"a","text":"Ibn Battuta","is_correct":false},{"id":"b","text":"Zheng He","is_correct":false},{"id":"c","text":"Marco Polo","is_correct":true},{"id":"d","text":"Leif Erikson","is_correct":false}],"explanation":"Marco Polo spent years in Asia in the late 13th century and dictated his famous account of the Mongol court."},{"id":"q6","question":"Which Norse explorer reached North America around the year 1000?","options":[{"id":"a","text":"Erik the Red","is_correct":false},{"id":"b","text":"Leif Erikson","is_correct":true},{"id":"c","text":"Olaf Tryggvason","is_correct":false},{"id":"d","text":"Harald Hardrada","is_correct":false}],"explanation":"Leif Erikson landed in a place the sagas call Vinland; the site at L''Anse aux Meadows confirms the Norse presence."},{"id":"q7","question":"Which Portuguese navigator first rounded the Cape of Good Hope, in 1488?","options":[{"id":"a","text":"Vasco da Gama","is_correct":false},{"id":"b","text":"Prince Henry the Navigator","is_correct":false},{"id":"c","text":"Bartolomeu Dias","is_correct":true},{"id":"d","text":"John Cabot","is_correct":false}],"explanation":"Dias proved ships could sail from the Atlantic into the Indian Ocean, paving the way for da Gama."},{"id":"q8","question":"Which British explorer charted much of the Pacific and Australia''s east coast in the 18th century?","options":[{"id":"a","text":"Francis Drake","is_correct":false},{"id":"b","text":"James Cook","is_correct":true},{"id":"c","text":"Walter Raleigh","is_correct":false},{"id":"d","text":"John Cabot","is_correct":false}],"explanation":"Cook''s three voyages mapped New Zealand, Australia''s east coast and many Pacific islands."}]'::jsonb,
  null,
  array['explorers', 'history', 'voyages', 'geography']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
