values (
  'es-trivia-grandes-exploradores',
  'Trivia de grandes exploradores: los viajes que cartografiaron el mundo',
  'Ocho preguntas sobre la era clásica de la exploración: Colón, Magallanes, Marco Polo y las rutas que unieron los continentes.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Qué explorador cruzó el Atlántico en 1492 y llegó al Caribe al servicio de la Corona española?","options":[{"id":"a","text":"Américo Vespucio","is_correct":false},{"id":"b","text":"Cristóbal Colón","is_correct":true},{"id":"c","text":"Fernando de Magallanes","is_correct":false},{"id":"d","text":"Vasco da Gama","is_correct":false}],"explanation":"Colón llegó al Caribe en octubre de 1492 en el primero de sus cuatro viajes."},{"id":"q2","question":"¿La expedición de qué explorador completó la primera vuelta al mundo?","options":[{"id":"a","text":"La de Fernando de Magallanes","is_correct":true},{"id":"b","text":"La de James Cook","is_correct":false},{"id":"c","text":"La de Francis Drake","is_correct":false},{"id":"d","text":"La de Vasco da Gama","is_correct":false}],"explanation":"Magallanes murió en Filipinas en 1521; Juan Sebastián Elcano concluyó la expedición en 1522."},{"id":"q3","question":"¿Qué navegante portugués llegó por primera vez a la India por mar, rodeando África?","options":[{"id":"a","text":"Vasco da Gama","is_correct":true},{"id":"b","text":"Bartolomé Díaz","is_correct":false},{"id":"c","text":"Pedro Álvares Cabral","is_correct":false},{"id":"d","text":"Fernando de Magallanes","is_correct":false}],"explanation":"Da Gama llegó a Calicut en 1498 y abrió la ruta marítima de Europa a la India."},{"id":"q4","question":"¿Quién fue el primer europeo en avistar la costa este del océano Pacífico, en 1513?","options":[{"id":"a","text":"Hernán Cortés","is_correct":false},{"id":"b","text":"Vasco Núñez de Balboa","is_correct":true},{"id":"c","text":"Francisco Pizarro","is_correct":false},{"id":"d","text":"Fernando de Magallanes","is_correct":false}],"explanation":"Balboa cruzó el istmo de Panamá y alcanzó el Pacífico, al que llamó mar del Sur."},{"id":"q5","question":"¿Qué mercader veneciano viajó a China y describió la corte de Kublai Kan?","options":[{"id":"a","text":"Ibn Battuta","is_correct":false},{"id":"b","text":"Zheng He","is_correct":false},{"id":"c","text":"Marco Polo","is_correct":true},{"id":"d","text":"Leif Erikson","is_correct":false}],"explanation":"Marco Polo pasó años en Asia a finales del siglo XIII y dictó su famoso relato de la corte mongola."},{"id":"q6","question":"¿Qué explorador nórdico llegó a América del Norte alrededor del año 1000?","options":[{"id":"a","text":"Erik el Rojo","is_correct":false},{"id":"b","text":"Leif Erikson","is_correct":true},{"id":"c","text":"Olaf Tryggvason","is_correct":false},{"id":"d","text":"Harald Hardrada","is_correct":false}],"explanation":"Leif Erikson llegó a un lugar que las sagas llaman Vinland; el yacimiento de L''Anse aux Meadows confirma la presencia nórdica."},{"id":"q7","question":"¿Qué navegante portugués dobló por primera vez el cabo de Buena Esperanza, en 1488?","options":[{"id":"a","text":"Vasco da Gama","is_correct":false},{"id":"b","text":"Enrique el Navegante","is_correct":false},{"id":"c","text":"Bartolomé Díaz","is_correct":true},{"id":"d","text":"John Cabot","is_correct":false}],"explanation":"Díaz demostró que se podía navegar del Atlántico al Índico, abriendo el camino a da Gama."},{"id":"q8","question":"¿Qué explorador británico cartografió gran parte del Pacífico y la costa este de Australia en el siglo XVIII?","options":[{"id":"a","text":"Francis Drake","is_correct":false},{"id":"b","text":"James Cook","is_correct":true},{"id":"c","text":"Walter Raleigh","is_correct":false},{"id":"d","text":"John Cabot","is_correct":false}],"explanation":"Los tres viajes de Cook cartografiaron Nueva Zelanda, la costa este de Australia y muchas islas del Pacífico."}]'::jsonb,
  null,
  array['exploradores', 'historia', 'viajes', 'geografía']::text[],
  3,
