insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-80s-movies-trivia',
  '80s Movies Trivia: 8 Iconic Films of the Decade',
  'Eight questions on the defining films of the 1980s: time machines, ghost hunters, cyborgs and the reveal that shook a galaxy.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Which 1985 film sends Marty McFly back in time in a DeLorean?","options":[{"id":"a","text":"Ghostbusters","is_correct":false},{"id":"b","text":"Back to the Future","is_correct":true},{"id":"c","text":"The Terminator","is_correct":false},{"id":"d","text":"Blade Runner","is_correct":false}],"explanation":"Robert Zemeckis''s Back to the Future made the DeLorean the most famous time machine in cinema."},{"id":"q2","question":"Which catchphrase comes from E.T. the Extra-Terrestrial (1982)?","options":[{"id":"a","text":"I''ll be back","is_correct":false},{"id":"b","text":"May the Force be with you","is_correct":false},{"id":"c","text":"E.T. phone home","is_correct":true},{"id":"d","text":"Here''s looking at you, kid","is_correct":false}],"explanation":"E.T.''s plea to ''phone home'' became one of the most quoted lines of the decade."},{"id":"q3","question":"Who directed Raiders of the Lost Ark (1981)?","options":[{"id":"a","text":"George Lucas","is_correct":false},{"id":"b","text":"Robert Zemeckis","is_correct":false},{"id":"c","text":"Steven Spielberg","is_correct":true},{"id":"d","text":"James Cameron","is_correct":false}],"explanation":"Spielberg directed the first Indiana Jones adventure from a story by George Lucas and Philip Kaufman."},{"id":"q4","question":"In which 1980 film does Darth Vader reveal he is Luke Skywalker''s father?","options":[{"id":"a","text":"Star Wars: A New Hope","is_correct":false},{"id":"b","text":"The Empire Strikes Back","is_correct":true},{"id":"c","text":"Return of the Jedi","is_correct":false},{"id":"d","text":"Ghostbusters","is_correct":false}],"explanation":"The reveal in The Empire Strikes Back is one of the most famous twists in film history."},{"id":"q5","question":"Which 1986 film gave us the line ''I feel the need... the need for speed''?","options":[{"id":"a","text":"Top Gun","is_correct":true},{"id":"b","text":"Iron Eagle","is_correct":false},{"id":"c","text":"The Right Stuff","is_correct":false},{"id":"d","text":"An Officer and a Gentleman","is_correct":false}],"explanation":"Maverick and Goose''s line sums up Top Gun, the Navy fighter-pilot hit of 1986."},{"id":"q6","question":"Which 1984 film stars Arnold Schwarzenegger as a cyborg sent from the future?","options":[{"id":"a","text":"Predator","is_correct":false},{"id":"b","text":"RoboCop","is_correct":false},{"id":"c","text":"The Terminator","is_correct":true},{"id":"d","text":"Commando","is_correct":false}],"explanation":"James Cameron''s The Terminator made Schwarzenegger a star and spawned a franchise."},{"id":"q7","question":"In The Shining (1980), which hotel does Jack Torrance look after over the winter?","options":[{"id":"a","text":"The Bates Motel","is_correct":false},{"id":"b","text":"The Overlook Hotel","is_correct":true},{"id":"c","text":"The Continental","is_correct":false},{"id":"d","text":"Hotel California","is_correct":false}],"explanation":"Stanley Kubrick''s film adapts Stephen King''s novel about the haunted Overlook Hotel."},{"id":"q8","question":"In Die Hard (1988), terrorists take over which Los Angeles skyscraper?","options":[{"id":"a","text":"Nakatomi Plaza","is_correct":true},{"id":"b","text":"Nakatomi Tower Two","is_correct":false},{"id":"c","text":"Wayne Enterprises","is_correct":false},{"id":"d","text":"Cyberdyne Systems","is_correct":false}],"explanation":"John McClane spends Christmas Eve fighting through Nakatomi Plaza in the action classic."}]'::jsonb,
  null,
  array['movies', '80s', 'film trivia', 'classics']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
