  '[{"id":"q1","question":"¿Qué película de 1985 envía a Marty McFly al pasado en un DeLorean?","options":[{"id":"a","text":"Los cazafantasmas","is_correct":false},{"id":"b","text":"Regreso al futuro","is_correct":true},{"id":"c","text":"Terminator","is_correct":false},{"id":"d","text":"Blade Runner","is_correct":false}],"explanation":"Regreso al futuro, de Robert Zemeckis, convirtió al DeLorean en la máquina del tiempo más famosa del cine."},{"id":"q2","question":"¿Qué frase inmortalizó E.T., el extraterrestre (1982)?","options":[{"id":"a","text":"«Volveré»","is_correct":false},{"id":"b","text":"«Que la Fuerza te acompañe»","is_correct":false},{"id":"c","text":"«E.T. teléfono... mi casa»","is_correct":true},{"id":"d","text":"«Siempre nos quedará París»","is_correct":false}],"explanation":"La petición de E.T. de llamar a su casa se volvió una de las líneas más citadas de la década."},{"id":"q3","question":"¿Quién dirigió En busca del arca perdida (1981)?","options":[{"id":"a","text":"George Lucas","is_correct":false},{"id":"b","text":"Robert Zemeckis","is_correct":false},{"id":"c","text":"Steven Spielberg","is_correct":true},{"id":"d","text":"James Cameron","is_correct":false}],"explanation":"Spielberg dirigió la primera aventura de Indiana Jones a partir de una historia de George Lucas y Philip Kaufman."},{"id":"q4","question":"¿En qué película de 1980 revela Darth Vader que es el padre de Luke Skywalker?","options":[{"id":"a","text":"Star Wars: Una nueva esperanza","is_correct":false},{"id":"b","text":"El imperio contraataca","is_correct":true},{"id":"c","text":"El retorno del Jedi","is_correct":false},{"id":"d","text":"Los cazafantasmas","is_correct":false}],"explanation":"La revelación de El imperio contraataca es uno de los giros más famosos de la historia del cine."},{"id":"q5","question":"¿De qué película de 1986 es la frase «siento la necesidad... la necesidad de velocidad»?","options":[{"id":"a","text":"Top Gun","is_correct":true},{"id":"b","text":"Águila de acero","is_correct":false},{"id":"c","text":"Elegidos para la gloria","is_correct":false},{"id":"d","text":"Oficial y caballero","is_correct":false}],"explanation":"La frase de Maverick y Goose resume Top Gun, el éxito de 1986 sobre pilotos de la Armada."},{"id":"q6","question":"¿Qué película de 1984 está protagonizada por Arnold Schwarzenegger como un cíborg enviado del futuro?","options":[{"id":"a","text":"Depredador","is_correct":false},{"id":"b","text":"RoboCop","is_correct":false},{"id":"c","text":"Terminator","is_correct":true},{"id":"d","text":"Commando","is_correct":false}],"explanation":"Terminator, de James Cameron, convirtió a Schwarzenegger en estrella y dio inicio a una franquicia."},{"id":"q7","question":"En El resplandor (1980), ¿qué hotel cuida Jack Torrance durante el invierno?","options":[{"id":"a","text":"El motel Bates","is_correct":false},{"id":"b","text":"El hotel Overlook","is_correct":true},{"id":"c","text":"El Continental","is_correct":false},{"id":"d","text":"El hotel California","is_correct":false}],"explanation":"La película de Stanley Kubrick adapta la novela de Stephen King sobre el embrujado hotel Overlook."},{"id":"q8","question":"En Die Hard (1988), ¿qué rascacielos de Los Ángeles toman los terroristas?","options":[{"id":"a","text":"La plaza Nakatomi","is_correct":true},{"id":"b","text":"La torre Nakatomi Dos","is_correct":false},{"id":"c","text":"Wayne Enterprises","is_correct":false},{"id":"d","text":"Cyberdyne Systems","is_correct":false}],"explanation":"John McClane pasa la Nochebuena peleando por la plaza Nakatomi en este clásico de acción."}]'::jsonb,
